import java.util.ArrayList;
import java.util.List;


public class PasarelaTarjetaCredito extends AbstractIntegracion implements Consultable, Transaccional, Auditable {
    private String tipoTarjeta;
    private List<String> historialEventos;

    public PasarelaTarjetaCredito(String id, String nombre, String estado, double latencia, String tipoTarjeta) {
        super(id, nombre, estado, latencia); // Invocación al constructor de la clase padre
        this.tipoTarjeta = tipoTarjeta;
        this.historialEventos = new ArrayList<>();
    }

    @Override
    public String mostrarDetalles() {
        return "Pasarela TC [" + identificador + "] - Proveedor: " + nombreProveedor + " (Tipo: " + tipoTarjeta + ")";
    }

    @Override
    public String consultarEstado() { 
        return estadoConexion; 
    }

    @Override
    public double cotizar(String detalleServicio) { 
        return 50.0; // Tarifa fija para consultas descriptivas
    }

    @Override
    public double cotizarMonto(double monto) { 
        return monto * 0.035; // Cálculo del 3.5% de comisión por pasarela
    }

    @Override
    public boolean cobrar(double monto) {
        registrarEvento("Cobro exitoso de: " + monto); // Bitácora automática al cobrar
        return true;
    }

    @Override
    public boolean reintegrar(double monto) {
        registrarEvento("Reintegro de: " + monto); // Bitácora automática al reintegrar
        return true;
    }

    @Override
    public void registrarEvento(String evento) { 
        historialEventos.add(evento); 
    }

    @Override
    public List<String> consultarHistorialEventos() { 
        return historialEventos; 
    }
}